/**
 * The route -> view dispatch. An exhaustive switch, so a route without a view is a compile
 * error.
 *
 * Owner: skeleton (core). View agents do not edit this file; they fill their own modules.
 */
import { renderConf } from './conf.js';
import type { AppContext, ViewResult } from './context.js';
import { h } from './dom.js';
import { renderGraph } from './graph.js';
import { renderReader } from './reader.js';
import { href, R, type Route, type RouteOf } from './router.js';
import { renderSelftest } from './selftest.js';
import { renderSituation, renderSituations } from './situations.js';
import { viewFrame } from './ui.js';

/** Design 3.8: "Nothing here". */
export function renderNotFound(ctx: AppContext, route: RouteOf<'notfound'>): ViewResult {
  void ctx;
  return {
    title: 'Nothing here',
    node: viewFrame('notfound', 'Nothing here',
      h('p', null, 'The address ', h('code', null, `#${route.path}`), ' does not match a page.'),
      h('p', null, h('a', { href: href(R.situations()) }, 'Situations'), ' · ', h('a', { href: href(R.req()) }, 'Rules')),
    ),
  };
}

export function renderRoute(ctx: AppContext, route: Route): ViewResult {
  switch (route.view) {
    case 'situations':
      return renderSituations(ctx, route);
    case 'situation':
      return renderSituation(ctx, route);
    case 'req':
      return renderReader(ctx, route);
    case 'conf':
      return renderConf(ctx, route);
    case 'graph':
      return renderGraph(ctx, route);
    case 'selftest':
      return renderSelftest(ctx, route);
    case 'notfound':
      return renderNotFound(ctx, route);
  }
}
